module euclidean_t_spanner
import math
struct Node{left int;right int;rep int;mask u64;cx f64;cy f64;r f64;span f64}
struct Ctx{mut:x [8]f64;y [8]f64;nodes [15]Node;mut:used int;n int;ec int;sep f64;edges [56]f64}
fn point_less(c Ctx,a int,b int,axis int)bool{mut a0,b0,a1,b1:=c.x[a],c.x[b],c.y[a],c.y[b];if axis==1{a0,b0,a1,b1=c.y[a],c.y[b],c.x[a],c.x[b]};return a0<b0||(a0==b0&&(a1<b1||(a1==b1&&a<b)))}
fn build(mut c Ctx,mask u64)int{at:=c.used;c.used++;mut ids:=[8]int{};mut n:=0;mut rep:=8;mut xmin,xmax,ymin,ymax:=f64(0),f64(0),f64(0),f64(0);for i in 0..c.n{if mask&(u64(1)<<i)!=0{if n==0{xmin=xmax=c.x[i];ymin=ymax=c.y[i]}else{xmin=math.min(xmin,c.x[i]);xmax=math.max(xmax,c.x[i]);ymin=math.min(ymin,c.y[i]);ymax=math.max(ymax,c.y[i])};ids[n]=i;n++;rep=math.min(rep,i)}};c.nodes[at]=Node{left:-1,right:-1,rep:rep,mask:mask,cx:(xmin+xmax)/2,cy:(ymin+ymax)/2,r:math.sqrt(math.pow((xmax-xmin)/2,2)+math.pow((ymax-ymin)/2,2)),span:math.max(xmax-xmin,ymax-ymin)};if n==1{return at};axis:=if xmax-xmin>=ymax-ymin{0}else{1};for i in 1..n{v:=ids[i];mut j:=i;for j>0&&point_less(c,v,ids[j-1],axis){ids[j]=ids[j-1];j--};ids[j]=v};mut lm,rm:=u64(0),u64(0);for i in 0..n{if i<n/2{lm|=u64(1)<<ids[i]}else{rm|=u64(1)<<ids[i]}};left:=build(mut c,lm);right:=build(mut c,rm);c.nodes[at].left=left;c.nodes[at].right=right;return at}
fn separated(c Ctx,a int,b int)bool{u,v:=c.nodes[a],c.nodes[b];return math.sqrt(math.pow(u.cx-v.cx,2)+math.pow(u.cy-v.cy,2))-u.r-v.r>=c.sep*math.max(u.r,v.r)}
fn cross_nodes(mut c Ctx,a int,b int){if separated(c,a,b){mut u,v:=c.nodes[a].rep,c.nodes[b].rep;if u>v{u,v=v,u};c.edges[2*c.ec]=f64(u);c.edges[2*c.ec+1]=f64(v);c.ec++;return};u,v:=c.nodes[a],c.nodes[b];if u.left<0{cross_nodes(mut c,v.left,a);cross_nodes(mut c,v.right,a)}else if v.left<0{cross_nodes(mut c,u.left,b);cross_nodes(mut c,u.right,b)}else if u.span>v.span{cross_nodes(mut c,u.left,b);cross_nodes(mut c,u.right,b)}else{cross_nodes(mut c,a,v.left);cross_nodes(mut c,a,v.right)}}
fn visit(mut c Ctx,at int){n:=c.nodes[at];if n.left<0{return};visit(mut c,n.left);visit(mut c,n.right);cross_nodes(mut c,n.left,n.right)}
@[export:'euclidean_t_spanner']
pub fn euclidean_t_spanner(input &f64,length usize,mut output &f64,capacity usize)i64{unsafe{if input==nil||length<6||length>18{return -1};raw:=input[0];t:=input[1];if !math.is_finite(raw)||!math.is_finite(t)||raw<2||raw>8||raw!=math.floor(raw)||t<1.5||t>4{return -1};n:=int(raw);if length!=usize(2+2*n){return -1};mut c:=Ctx{n:n,sep:4*(t+1)/(t-1)};for i in 0..n{x:=input[2+2*i];y:=input[3+2*i];if !math.is_finite(x)||!math.is_finite(y)||math.abs(x)>1000||math.abs(y)>1000||x!=math.floor(x)||y!=math.floor(y){return -1};for j in 0..i{if c.x[j]==x&&c.y[j]==y{return -1}};c.x[i]=x;c.y[i]=y};root:=build(mut c,(u64(1)<<n)-1);visit(mut c,root);needed:=1+2*c.ec;if output==nil||capacity<usize(needed){return -2};output[0]=f64(c.ec);for i in 0..2*c.ec{output[i+1]=c.edges[i]};return i64(needed)}}
